#!/usr/bin/env python3
import math, random, sys

# Physical constants (SI)
G = 6.67430e-11            # m^3 kg^-1 s^-2
c = 2.99792458e8          # m s^-1
hbar = 1.054571817e-34    # J s
k_B = 1.380649e-23        # J K^-1
M_sun = 1.98847e30        # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def horizon_area(r_s):
    """Area of a spherical horizon A = 4π r_s^2"""
    return 4 * math.pi * r_s**2

def hawking_temperature(M):
    """Hawking temperature T_H = ħ c^3 / (8π G k_B M)"""
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def bh_entropy(A, lP_sq):
    """Bekenstein-Hawking entropy S = k_B A / (4 l_P^2)"""
    return k_B * A / (4 * lP_sq)

def random_bh_mass():
    """Return a random astrophysical mass between 5 and 50 solar masses."""
    return random.uniform(5, 50) * M_sun

def run_trials(num_trials=10000, seed=42):
    random.seed(seed)
    lP_sq = (G * hbar / c**3) ** 2  # Planck length squared
    logs = []  # store (M, T_H, S) for possible entropy check
    for _ in range(num_trials):
        M = random_bh_mass()
        r_s = schwarzschild_radius(M)
        A = horizon_area(r_s)
        T = hawking_temperature(M)
        S = bh_entropy(A, lP_sq)
        logs.append((M, T, S))
    return logs

def main():
    logs = run_trials()
    # Example: print the first few entries (in real use the data would be saved)
    for i, (M, T, S) in enumerate(logs[:10], 1):
        print(f"Trial {i}: M={M:.3e} kg, T_H={T:.3e} K, S={S:.3e} J/K")

if __name__ == "__main__":
    main()

